
package kr.ac.knue.cms.auth;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.test.web.servlet.MockMvc;import java.util.List;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(AuthController.class) class AuthControllerTest{@Autowired MockMvc mvc;@MockBean AuthenticationPort auth;@MockBean SessionService sessions;@Test void admin_login_sets_cookie_and_returns_r09() throws Exception{when(auth.authenticate("admin","admin")).thenReturn(new SessionUser(null,"admin","admin","시스템관리자",List.of("R09")));when(sessions.create("admin")).thenReturn("S1");mvc.perform(post("/api/auth/login").contentType("application/json").content("{\"loginId\":\"admin\",\"password\":\"admin\"}" )).andExpect(status().isOk()).andExpect(header().string("Set-Cookie",org.hamcrest.Matchers.containsString("SESSION=S1"))).andExpect(jsonPath("$.success").value(true)).andExpect(jsonPath("$.data.roles[0]").value("R09"));}@Test void missing_password_returns_field_error() throws Exception{mvc.perform(post("/api/auth/login").contentType("application/json").content("{\"loginId\":\"admin\"}" )).andExpect(status().isBadRequest()).andExpect(jsonPath("$.error.fields.password").exists());}}
